<?php
namespace ProjectPress\Admin\Manager\Projects;
use DateTimeInterface;use ProjectPress\Admin\Manager\Manager;use ProjectPress\Assets\Assets;use ProjectPress\Includes\Functions\Helpers\RequestHelper;use ProjectPress\Includes\Project\Core\Project as DomainProject;use ProjectPress\Includes\Project\Core\ProjectPermissions;use ProjectPress\Includes\Project\Core\TeamRepository;use ProjectPress\Includes\Project\Integration\ProjectExtensionRegistry;use ProjectPress\Includes\Project\ProjectManager as DomainProjectManager;use ProjectPress\Includes\Project\Tracking\ActivityRepository;
if(!defined('ABSPATH')){exit;} final class ProjectManager extends Manager{
 private DomainProjectManager $projects;private ?DomainProject $project=null;private TeamRepository $teams;private ActivityRepository $activity;private Project $details;private Teams $members;private Tasks $tasks;private Milestones $milestones;private Planning $planning;private Collaboration $collaboration;private WorkspaceContent $content;
 private array $tabs=array('overview'=>'Overview','details'=>'Details','members'=>'Members','planning'=>'Planning','tasks'=>'Tasks','milestones'=>'Milestones','documents'=>'Documents','discussions'=>'Discussions','notes'=>'Notes','files'=>'Files','activity'=>'Activity','settings'=>'Settings');
 public function __construct(){$this->page='projects';$this->projects=DomainProjectManager::get_instance();$permissions=new ProjectPermissions();$this->teams=new TeamRepository();$this->activity=new ActivityRepository();$this->details=new Project($this->projects,$permissions);$this->members=new Teams($this->projects,$permissions);$this->tasks=new Tasks($this->projects,$permissions);$this->milestones=new Milestones($this->projects,$permissions);$this->planning=new Planning($this->projects);$this->collaboration=new Collaboration($this->projects,$permissions);$this->content=new WorkspaceContent($this->projects,$permissions);add_action('admin_post_projectpress_workspace_project_details_save',array($this->details,'handle_save'));add_action('admin_post_projectpress_workspace_project_team_assign',array($this->members,'handle_assign'));add_action('admin_post_projectpress_workspace_project_team_remove',array($this->members,'handle_remove'));add_action('admin_post_projectpress_workspace_task_save',array($this->tasks,'handle_save'));add_action('admin_post_projectpress_workspace_task_delete',array($this->tasks,'handle_delete'));add_action('admin_post_projectpress_workspace_milestone_save',array($this->milestones,'handle_save'));add_action('admin_post_projectpress_workspace_milestone_delete',array($this->milestones,'handle_delete'));add_action('admin_post_projectpress_workspace_collaboration_save',array($this->collaboration,'handle_save'));add_action('admin_post_projectpress_workspace_collaboration_delete',array($this->collaboration,'handle_delete'));add_action('admin_post_projectpress_workspace_content_save',array($this->content,'handle_save'));add_action('admin_post_projectpress_workspace_content_comment',array($this->content,'handle_comment'));add_action('admin_post_projectpress_workspace_setting_save',array($this->content,'handle_setting_save'));add_action('admin_post_projectpress_workspace_content_delete',array($this->content,'handle_delete'));}
 public function register_assets(Assets $assets):void{$this->register_page_assets($assets,array('projectpress'),'projects');}
 public function render(string $tab='',string $form=''):void{$identifier=RequestHelper::get_text('project','');if(''===$identifier)$identifier=(string)RequestHelper::get_integer('project_id',0);$resolved=$this->projects->resolve($identifier);if(is_wp_error($resolved))wp_die(esc_html($resolved->get_error_message()));$this->project=$resolved;$tabs=$this->workspace_tabs();$aliases=array_combine(array_keys($tabs),array_keys($tabs));$tab=$this->normalize_route(''!==$tab?$tab:RequestHelper::get_key('tab','overview'),$aliases,'overview');$this->tabs=$tabs;$this->header($this->project->get_name());$this->render_workspace_header($tab);$this->render_tab($tab);$this->footer();}
 private function workspace_tabs():array{$tabs=$this->tabs;foreach(ProjectExtensionRegistry::get_instance()->workspace_tabs() as$key=>$definition){$tabs[$key]=(string)$definition['label'];}return apply_filters('projectpress_project_workspace_tabs',$tabs,$this->project);}
 private function render_workspace_header(string $active):void{?><div class="card card-body mb-4"><div class="d-flex flex-wrap justify-content-between gap-3"><div><div class="d-flex gap-2 mb-2"><span class="badge text-bg-secondary"><?php echo esc_html($this->project->get_key());?></span><span class="badge text-bg-light"><?php echo esc_html($this->humanise($this->project->get_status()));?></span><span class="badge text-bg-light"><?php echo esc_html($this->humanise($this->project->get_priority()));?></span></div><p class="text-secondary mb-0"><?php echo esc_html($this->project->get_description());?></p></div><a class="btn btn-outline-secondary" href="<?php echo esc_url(admin_url('admin.php?page=projectpress&group=project-manager&tab=projects'));?>"><?php esc_html_e('Back to Projects','projectpress');?></a></div></div><nav class="nav nav-tabs flex-nowrap overflow-auto mb-4"><?php foreach($this->tabs as$key=>$label):?><a class="nav-link <?php echo $key===$active?'active':'';?>" href="<?php echo esc_url($this->workspace_url($key));?>"><?php echo esc_html($label);?></a><?php endforeach;?></nav><?php }
 private function render_tab(string $tab):void{do_action('projectpress_project_workspace_before_tab',$this->project,$tab);switch($tab){case'overview':$this->render_overview();break;case'details':$this->details->render($this->project);break;case'members':$this->members->render($this->project);break;case'planning':$this->planning->render($this->project);break;case'tasks':$this->tasks->render($this->project);break;case'milestones':$this->milestones->render($this->project);break;case'documents':$this->collaboration->render_documents($this->project);break;case'files':$this->collaboration->render_files($this->project);break;case'notes':case'discussions':case'activity':case'settings':$this->content->render($this->project,$tab);break;default:$this->render_extension_tab($tab);break;}do_action('projectpress_project_workspace_after_tab',$this->project,$tab);}
 private function render_extension_tab(string $tab):void{$definition=ProjectExtensionRegistry::get_instance()->workspace_tabs()[$tab]??null;if(!$definition)return;$allowed=!isset($definition['permission_callback'])||null===$definition['permission_callback']||call_user_func($definition['permission_callback'],$this->project);if(!$allowed){wp_die(esc_html__('You do not have permission to view this project section.','projectpress'));}call_user_func($definition['render_callback'],$this->project);}
 private function render_overview():void{$id=$this->project->get_id();$owner=$this->project->get_owner_id()?get_user_by('id',$this->project->get_owner_id()):false;$teams=$this->teams->for_project($id);$activity=$this->activity->for_project($id,5);?><div class="row g-3 mb-4"><?php $this->stat(__('Status','projectpress'),$this->humanise($this->project->get_status()));$this->stat(__('Priority','projectpress'),$this->humanise($this->project->get_priority()));$this->stat(__('Visibility','projectpress'),$this->humanise($this->project->get_visibility()));$this->stat(__('Teams','projectpress'),(string)count($teams));?></div><div class="row g-4"><div class="col-xl-7"><div class="card card-body"><h2 class="h4"><?php esc_html_e('Project summary','projectpress');?></h2><p><strong><?php esc_html_e('Owner:','projectpress');?></strong> <?php echo esc_html($owner?$owner->display_name:__('Not assigned','projectpress'));?></p><p><strong><?php esc_html_e('Start:','projectpress');?></strong> <?php echo esc_html($this->format_date($this->project->get_start_date()));?></p><p class="mb-0"><strong><?php esc_html_e('Target:','projectpress');?></strong> <?php echo esc_html($this->format_date($this->project->get_target_end_date()));?></p></div></div><div class="col-xl-5"><div class="card card-body"><h2 class="h4"><?php esc_html_e('Recent activity','projectpress');?></h2><?php if(empty($activity)):?><p class="text-secondary mb-0"><?php esc_html_e('No activity yet.','projectpress');?></p><?php endif;foreach($activity as$item):?><div class="border-bottom py-2"><?php echo esc_html((string)($item['activity_summary']?:$this->humanise((string)$item['action'])));?></div><?php endforeach;?></div></div></div><?php }
 private function stat(string $label,string $value):void{?><div class="col-sm-6 col-xl-3"><div class="card card-body"><span class="small text-secondary"><?php echo esc_html($label);?></span><strong><?php echo esc_html($value);?></strong></div></div><?php }
 private function workspace_url(string $tab):string{return add_query_arg(array('page'=>'projectpress','group'=>'projects','project_id'=>$this->project->get_id(),'tab'=>$tab),admin_url('admin.php'));}private function humanise(string $v):string{return ucwords(str_replace('_',' ',$v));}private function format_date(?DateTimeInterface $d):string{return $d?$d->format('j M Y'):__('Not set','projectpress');}
}
